                seen.add((r,c))
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<H and 0<=b<dov and g[a][b]==color and (a,b) not in seen:
                                seen.add((a,b)); st.append((a,b))
    return comps

