            if v!=0 and v!=4: pts.append((v,r,c))
    outpos=[(r,c,b[r][c]) for r in range(len(b)) for c in range(7) if b[r][c]!=0]
    print('=== demo',n,'out positions:',outpos)
    # For each output cell, find nearest input comp cell (Manhattan), show top 2
    for r,c,v in outpos:
        dists=sorted((abs(p[1]-r)+abs(p[2]-c),p) for p in pts)
        print('  ',(r,c,v),'nearest:',dists[:2])
